# Check if columns with "fill value appearing in boundary" are excluded
def check_boundary_pattern(demos):
    for i, demo in enumerate(demos):
        in_grid = demo['input']
        out_grid = demo['output']
        h, w = len(in_grid), len(in_grid[0])

        bg = 1 if i == 0 else (5 if i == 1 else 2)

        # Find fill columns (where some changed value appears between row 1 and h-2)
        fill_cols = set()
        for c in range(w):
            for r in range(1, h-1):
                if out_grid[r][c] != in_grid[r][c]:
                    fill_cols.add(c)

        # Check if the fill value appears at top or bottom in that column
        # And if so, is it NOT filled?

        for c in range(w):
            has_special_bottom = in_grid[h-1][c] != bg
            has_special_top = in_grid[0][c] != bg

            is_filled = c in fill_cols
            filled_value = None
            for r in range(1, h-1):
                if out_grid[r][c] != in_grid[r][c]:
                    filled_value = out_grid[r][c]
                    break

            print(f"Demo {i}, col {c}: top={in_grid[0][c]} bot={in_grid[h-1][c]} fill={filled_value} filled={is_filled}")

check_boundary_pattern(demos)

# Need to figure out what the "marker value" is for each demo
# Let me count unique boundary values (top/brow)

def analyze_marker(demos):
    for i, demo in enumerate(demos):
        in_grid = demo['input']
        h, w = len(in_grid), len(in_grid[0])

        # Get boundary values for each column
        boundary_vals = {}
        for c in range(w):
            top = in_grid[0][c]
            bot = in_grid[h-1][c]
            if top != bot:
                boundary_vals[c] = f"({top},{bot})"
            elif top != 1 and c not in [0,1,3,4,5] and i == 0:
                pass  # This is background

        print(f"\nDemo {i}: boundary variations")
        for c, bv in sorted(boundary_vals.items()):
            print(f"  Col {c}: {bv}")

        # Now find non-bg values
        from collections import Counter
        all_vals = [val for row in in_grid for val in row]
        cnts = Counter(all_vals)
        bg = cnts.most_common(1)[0][0]

        # Find non-bg boundary values
        non_bg_boundary = []
        for c in range(w):
            for val in [in_grid[0][c], in_grid[h-1][c]]:
                if val != bg:
                    non_bg_boundary.append((c, in_grid[0][c], in_grid[h-1][c]))
        print(f"Non-bg boundary: {non_bg_boundary}")

analyze_marker(demos)

